          {
            "listen": "prerequest",
            "script": {
              "id": "fd554123-3124-444c-a4ab-a2ed3c21b794",
              "type": "text/javascript",
              "exec": [
                "try {",
                "    const response = await pm.sendRequest({",
                "        url: \"https://postman-echo.com/get\",",
                "        method: \"GET\"",
                "    });",
                "",
                "    console.log(response.json());",
